/**
 * What a save stores about perk choices: the banned perks, the first pick and first trade-off, and
 * the auto-pick switch with its priority order — as the save holds them, before any tool shapes them.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    SavePerkChoices
 * depends    —
 * used by    src/save/perks/index, src/save/perks/read
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

/** The perk choices a save records. Indices are perk catalog indices; `null` means none chosen. */
export interface SavePerkChoices {
  /** `bannedPerksIndex`: every banned perk, sorted, without repeats. */
  bannedIndices: number[]
  /** `firstPerkIndex`, or `null` when the save holds none. */
  firstPerkIndex: number | null
  /** `firstTradeOffPerkIndex`, or `null` when the save holds none. */
  firstTradeOffPerkIndex: number | null
  /** `autoPickPerk`. */
  autoPickPerk: boolean
  /** `autoPickOrder`, the auto-pick priority, with the save's empty `-1` slots dropped. */
  autoPickOrder: number[]
}
